<!doctype html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers · Puihaha Electric</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>
:root{--purple:#6f43b5;--page:#f5f5f7;--line:#ecebef}*{box-sizing:border-box}body{margin:0;background:var(--page);color:#25242b;font-family:Inter,system-ui,sans-serif}.app{min-height:100vh;display:flex}.sidebar{width:245px;background:#fff;border-right:1px solid #e8e7eb;padding:28px 18px;display:flex;flex-direction:column;flex:none}.brand{font-size:1.1rem;font-weight:800;padding:0 14px 34px}.brand i{color:#116bd1;font-size:1.4rem;margin-right:8px}.nav-label{font-size:.7rem;text-transform:uppercase;color:#aaa5b0;padding:0 14px 10px;font-weight:700}.side-link{display:flex;align-items:center;gap:14px;color:#5f5b64;text-decoration:none;padding:12px 14px;border-radius:9px;margin:2px 0;font-size:.93rem}.side-link i{width:20px;text-align:center}.side-link:hover{background:#f4f0fb;color:var(--purple)}.side-link.active{background:var(--purple);color:#fff}.side-bottom{margin-top:auto}.logout{color:#ed756e}.main{flex:1;min-width:0}.topbar{height:100px;background:#fff;border-bottom:1px solid #ecebef;display:flex;align-items:center;justify-content:space-between;padding:0 38px}.greeting small{display:block;color:#777;margin-bottom:4px}.greeting h1{font-size:1.55rem;margin:0;font-weight:800}.top-search{width:290px;height:44px;border:0;background:#f5f5f6;border-radius:24px;padding:0 18px}.avatar{width:39px;height:39px;border-radius:50%;background:linear-gradient(135deg,#d5a47c,#6b3e2b);color:#fff;display:grid;place-items:center;font-weight:700}.content{padding:34px 38px}.content-card{background:#fff;border-radius:14px;padding:26px 20px 20px;box-shadow:0 2px 7px #1e152008}.heading{display:flex;align-items:center;justify-content:space-between;padding-bottom:23px}.heading h2{font-size:1.25rem;font-weight:800;margin:0}.filter-btn{border:1px solid #dedce2;background:#fff;border-radius:8px;padding:10px 14px}.btn-dark{border-radius:8px}.filter-row{border-top:1px solid var(--line);padding:18px 0}.filter-row input,.filter-row select{height:43px;border-radius:8px}.table-wrap{border:1px solid #e5e3e7;border-radius:12px;overflow:auto}.customer-table{min-width:850px;margin:0}.customer-table th{background:#f7f7f8;color:#76727c;font-weight:500;padding:15px 16px;font-size:.84rem;border:0}.customer-table td{padding:16px;border-top:1px solid #efedf0;vertical-align:middle;font-size:.9rem}.customer-name{font-weight:650}.muted{color:#8a8690;font-size:.78rem}.status{display:inline-flex;padding:6px 13px;border-radius:20px;font-size:.78rem;font-weight:650}.active{color:#1aae78;background:#e4f8ef}.inactive{color:#ee6b56;background:#ffebe6}.suspended{color:#9a6d11;background:#fff4d6}.pager-row{display:flex;justify-content:space-between;align-items:center;padding:18px 10px 0;color:#777}.pagination{gap:5px}.page-link{border:0!important;color:#5d5962;border-radius:7px!important}.active>.page-link{background:var(--purple);color:#fff}.mobile-toggle{display:none}@media(max-width:700px){.sidebar{position:fixed;left:-245px;z-index:3;height:100%;transition:.2s}.sidebar.open{left:0}.mobile-toggle{display:block;border:0;background:transparent;font-size:1.4rem;margin-right:10px}.topbar{height:80px;padding:0 16px}.top-search{display:none}.content{padding:18px 14px}.heading{align-items:flex-start;gap:12px;flex-direction:column}.heading>div{width:100%}.heading .btn-dark{width:100%}}
</style></head>
<body><div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><i class="bi bi-lightning-charge-fill"></i>Puihaha Electric</div><div class="nav-label">Workspace</div><a class="side-link" href="<?= base_url() ?>"><i class="bi bi-house-door"></i>Home</a><a class="side-link" href="<?= base_url('accounts') ?>"><i class="bi bi-grid-1x2"></i>Dashboard</a><a class="side-link active" href="<?= base_url('accounts') ?>"><i class="bi bi-people"></i>Customers</a><a class="side-link" href="<?= base_url('account/create') ?>"><i class="bi bi-person-plus"></i>Add customer</a><a class="side-link" href="<?= base_url('services') ?>"><i class="bi bi-lightning"></i>Services</a><div class="side-bottom"><form action="<?= base_url('logout') ?>" method="post"><?= csrf_field() ?><button class="side-link logout border-0 bg-transparent w-100 text-start" type="submit"><i class="bi bi-box-arrow-left"></i>Logout</button></form></div></aside><section class="main"><header class="topbar"><div class="d-flex align-items-center"><button class="mobile-toggle" onclick="sidebar.classList.toggle('open')"><i class="bi bi-list"></i></button><div class="greeting"><small>Good day, <?= esc($username) ?></small><h1>Welcome back 👋</h1></div></div><div class="d-flex align-items-center gap-3"><input class="top-search" placeholder="Search now"><i class="bi bi-bell fs-5 text-secondary"></i><div class="avatar"><?= esc(strtoupper(substr((string)$username,0,1))) ?></div></div></header><main class="content"><?php if($message=session()->getFlashdata('success')): ?><div class="alert alert-success"><?= esc($message) ?></div><?php endif; ?><?php if($message=session()->getFlashdata('error')): ?><div class="alert alert-danger"><?= esc($message) ?></div><?php endif; ?><div class="content-card"><div class="heading"><h2>Recent Customers</h2><div class="d-flex gap-2"><button class="filter-btn" type="button" onclick="filters.classList.toggle('d-none')"><i class="bi bi-funnel me-2"></i>Filter</button><a class="btn btn-dark text-white" href="<?= base_url('account/create') ?>"><i class="bi bi-plus-lg me-2"></i>Add New Customer</a></div></div><form id="filters" class="filter-row row g-2 <?= ($filters['search']||$filters['status']||$filters['type'])?'':'d-none' ?>" method="get" action="<?= base_url('accounts') ?>"><div class="col-lg-5"><input class="form-control" name="search" placeholder="Search customers..." value="<?= esc($filters['search']) ?>"></div><div class="col-sm-6 col-lg-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['active','inactive','suspended'] as $option): ?><option value="<?= $option ?>" <?= $filters['status']===$option?'selected':'' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select></div><div class="col-sm-6 col-lg-3"><select class="form-select" name="type"><option value="">All connection types</option><?php foreach(['residential','commercial','industrial'] as $option): ?><option value="<?= $option ?>" <?= $filters['type']===$option?'selected':'' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select></div><div class="col-lg-1"><button class="btn btn-dark w-100 h-100" type="submit"><i class="bi bi-search"></i></button></div></form><div class="table-wrap"><table class="table customer-table"><thead><tr><th>Name</th><th>Customer ID</th><th>Email</th><th>Phone</th><th>Status</th><th class="text-end">Action</th></tr></thead><tbody><?php if(empty($accounts)): ?><tr><td colspan="6" class="text-center py-5 text-muted">No customer accounts found.</td></tr><?php endif; ?><?php foreach($accounts as $account): ?><tr><td><div class="customer-name"><?= esc($account['customer_name']) ?></div><div class="muted"><?= esc($account['address']) ?></div></td><td><strong>#<?= esc($account['account_number']) ?></strong></td><td><?= esc($account['email']?:'—') ?></td><td><?= esc($account['phone']?:'—') ?></td><td><span class="status <?= esc($account['status']) ?>"><?= ucfirst(esc($account['status'])) ?></span></td><td class="text-end"><a class="text-secondary fs-5" href="<?= base_url('account/'.$account['id']) ?>"><i class="bi bi-three-dots-vertical"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php $page=$pager->getCurrentPage();$pages=$pager->getPageCount();$query=array_filter($filters);if($pages>1): ?><div class="pager-row"><span>Showing page <?= $page ?> of <?= $pages ?></span><nav><ul class="pagination"><li class="page-item"><a class="page-link" href="<?= $page>1?base_url('accounts?'.http_build_query(array_merge($query,['page'=>$page-1]))):'#' ?>">‹</a></li><?php for($n=1;$n<=$pages;$n++): ?><li class="page-item <?= $n===$page?'active':'' ?>"><a class="page-link" href="<?= base_url('accounts?'.http_build_query(array_merge($query,['page'=>$n]))) ?>"><?= $n ?></a></li><?php endfor; ?><li class="page-item"><a class="page-link" href="<?= $page<$pages?base_url('accounts?'.http_build_query(array_merge($query,['page'=>$page+1]))):'#' ?>">›</a></li></ul></nav></div><?php endif; ?></div></main></section></div></body></html>
